<?php use Hls\Http\View as V; ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Nomor<input name="adjustment_ref" required></label><label>Tanggal<input type="date" name="adjustment_date" value="<?= date('Y-m-d') ?>" required></label><label>Cabang<select name="branch_id"><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code']) ?></option><?php endif; endforeach ?></select></label><label>Gudang<select name="warehouse_id"><?php foreach($warehouses as $w): if($access->branch((int)$w['branch_id'])): ?><option value="<?= (int)$w['id'] ?>"><?= V::escape($w['code']) ?></option><?php endif; endforeach ?></select></label><label>Alasan<input name="reason" required></label><label>Barang<select name="item_id[]"><?php foreach($items as $i): ?><option value="<?= (int)$i['id'] ?>"><?= V::escape($i['code'].' - '.$i['name']) ?></option><?php endforeach ?></select></label><label>Penyesuaian<input name="quantity_change[]" type="number" step="0.001" required></label><button class="button button-primary">Simpan Draft</button></form></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Cabang</th><th>Gudang</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['adjustment_ref']) ?></td><td><?= V::escape($r['adjustment_date']) ?></td><td><?= V::escape($r['branch_code']) ?></td><td><?= V::escape($r['warehouse_code']) ?></td><td><?= V::escape($r['status']) ?></td><td><a href="<?= $this->url('/inventory/adjustment-detail?id='.(int)$r['id']) ?>">Detail</a></td></tr><?php endforeach ?></tbody></table></div></section>
